import{_ as s,C as i,o as t,c as n,E as o,a2 as r}from"./chunks/framework.Cm6XCzck.js";const m=JSON.parse('{"title":"数字员工每日观察 001 — Agent 能力之前，先有岗位、所有权与权限","description":"","frontmatter":{"title":"数字员工每日观察 001 — Agent 能力之前，先有岗位、所有权与权限","date":"2026-08-02","column":"digital-employee","category":"daily","summary":"Workday、ServiceNow 与 Microsoft 正在把 AI 工作者从一次性 Agent 转变为具有持久所有权、明确岗位、有限权限与生命周期治理的组织对象。","cover":"/assets/covers/position-ownership-authority-cover-v2.jpg","sources":["Workday Agent System of Record","ServiceNow Autonomous Workforce","Microsoft Agent 365"],"outline":"deep"},"headers":[],"relativePath":"zh/digital-employee/2026-08-02-position-ownership-authority.md","filePath":"zh/digital-employee/2026-08-02-position-ownership-authority.md","lastUpdated":1787407830000}'),l={name:"zh/digital-employee/2026-08-02-position-ownership-authority.md"};function p(c,e,h,d,g,u){const a=i("ArticleCover");return t(),n("div",null,[o(a,{image:"/assets/covers/position-ownership-authority-cover-v2.jpg",kicker:"数字员工 · 每日观察 001",title:"Agent 能力之前，先有岗位、所有权与权限",summary:"数字员工首先是具有岗位、责任所有者和有限权限的组织对象；Agent 能力只是被绑定在这一契约之下的执行资源。",version:"DD001",status:"Research Note · 2026-08-02",languageHref:"/en/digital-employee/2026-08-02-position-ownership-authority",languageLabel:"English"}),e[0]||(e[0]=r(`<h1 id="数字员工每日观察-001-—-agent-能力之前-先有岗位、所有权与权限" tabindex="-1">数字员工每日观察 001 — Agent 能力之前，先有岗位、所有权与权限 <a class="header-anchor" href="#数字员工每日观察-001-—-agent-能力之前-先有岗位、所有权与权限" aria-label="Permalink to &quot;数字员工每日观察 001 — Agent 能力之前，先有岗位、所有权与权限&quot;">​</a></h1><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>当前企业数字劳动力产品最强的共同信号，并不是又出现了一个更强的推理模型，而是管理对象正在从“没有组织身份的 Agent”转向“受管理的组织对象”。</p><p>Workday 强调注册、负责人、角色、权限、生命周期、成本和价值；ServiceNow 把 AI Specialist 放进明确岗位、技能任务、权限、工作流政策和人工升级中；Microsoft Agent 365 则提供 Agent Registry、Owner 分配、访问治理、激活、阻断与退役机制。</p><p>本次研究判断是：</p><blockquote><p>数字员工首先应由岗位、责任所有者和有限权限定义。Agent 能力只是被绑定在这一组织契约之下的执行资源。</p></blockquote><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><h3 id="入选的官方资料" tabindex="-1">入选的官方资料 <a class="header-anchor" href="#入选的官方资料" aria-label="Permalink to &quot;入选的官方资料&quot;">​</a></h3><ol><li><strong>Workday Agent System of Record</strong>：入选原因是它把 Agent 放入混合劳动力体系，并明确注册、问责、可见性、权限、分析和生命周期管理。</li><li><strong>ServiceNow Autonomous Workforce</strong>：入选原因是它明确从通用 Agent 转向有岗位、有技能、有交付物、有权限和升级条件的 AI Specialist。</li><li><strong>Microsoft Agent 365 治理文档</strong>：入选原因是它提供了具体管理动作，包括 Registry、Owner 分配、激活、阻断、政策、访问治理和生命周期管理。</li></ol><p>这些都是厂商官方资料，可以用于判断产品方向与已公开的管理机制；其中性能、规模和采用率等厂商声明，不能在缺少独立验证时直接视为外部实证。</p><h2 id="observation" tabindex="-1">Observation <a class="header-anchor" href="#observation" aria-label="Permalink to &quot;Observation&quot;">​</a></h2><h3 id="_1-管理对象正在变成持久对象" tabindex="-1">1. 管理对象正在变成持久对象 <a class="header-anchor" href="#_1-管理对象正在变成持久对象" aria-label="Permalink to &quot;1. 管理对象正在变成持久对象&quot;">​</a></h3><p>Workday 将 Agent System of Record 描述为统一注册和管理第一方、第三方 Agent 的位置，其生命周期覆盖注册、配置、激活和停用。单次 Session 结束后，Agent 仍然作为组织资源存在。</p><p>Microsoft 同样提供 Agent Registry，以及安装、激活、阻断、重新分配 Owner 和删除等治理动作。这说明企业中的 Agent 已经不再只是代码或聊天 Session。</p><h3 id="_2-所有权正在成为必填项" tabindex="-1">2. 所有权正在成为必填项 <a class="header-anchor" href="#_2-所有权正在成为必填项" aria-label="Permalink to &quot;2. 所有权正在成为必填项&quot;">​</a></h3><p>Workday 追问：谁负责这个 Agent、它是什么角色、成本是多少、是否创造价值。Microsoft 把没有 Owner 的 Agent 明确视为治理缺口，并提供 Owner 分配能力；Microsoft Entra 又进一步提供 Agent Sponsor 与生命周期工作流。</p><p>所以 Owner 不是装饰性元数据，而是权限审批、风险处置、持续改进、停用和问责的入口。</p><h3 id="_3-明确岗位与工作范围正在替代通用自主性" tabindex="-1">3. 明确岗位与工作范围正在替代通用自主性 <a class="header-anchor" href="#_3-明确岗位与工作范围正在替代通用自主性" aria-label="Permalink to &quot;3. 明确岗位与工作范围正在替代通用自主性&quot;">​</a></h3><p>ServiceNow 的 Autonomous Workforce 以 AI Specialist 为单位，例如一级服务台 AI Specialist。它们有特定岗位、技能、任务、交付要求、政策和升级条件。产品表达不是“一个 Agent 什么都能做”，而是“一个受治理的 Specialist 完成某一类组织工作”。</p><p>Workday 也强调 Role-based Agent Support，即围绕职责与权限定义 Agent。</p><h3 id="_4-权限边界被显式化" tabindex="-1">4. 权限边界被显式化 <a class="header-anchor" href="#_4-权限边界被显式化" aria-label="Permalink to &quot;4. 权限边界被显式化&quot;">​</a></h3><p>ServiceNow 把自主执行与工作流政策、可追踪性和人工升级绑定。Microsoft 使用权限、政策、Access Package、阻断和最小权限控制。Workday 区分 Agent 以自身身份执行，还是代表某个用户执行，并强调精确的身份与权限控制。</p><p>共同方向已经很清楚：有价值的自主性，是边界内的权限，不是无限制行动。</p><h2 id="discussion" tabindex="-1">Discussion <a class="header-anchor" href="#discussion" aria-label="Permalink to &quot;Discussion&quot;">​</a></h2><h3 id="岗位应当成为第一组织抽象" tabindex="-1">岗位应当成为第一组织抽象 <a class="header-anchor" href="#岗位应当成为第一组织抽象" aria-label="Permalink to &quot;岗位应当成为第一组织抽象&quot;">​</a></h3><p>Agent 说明谁来执行；岗位说明组织为什么允许这个执行体存在。</p><p>岗位可以定义：</p><ul><li>工作目的；</li><li>责任范围；</li><li>可接受的工作类型；</li><li>可使用的工具和数据；</li><li>决策权限；</li><li>升级义务；</li><li>服务要求；</li><li>责任所有者；</li><li>证据与评估要求。</li></ul><p>这些定义可以在模型、Provider、Session 或具体实现发生变化时保持稳定。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>组织</span></span>
<span class="line"><span>  ↓ 定义</span></span>
<span class="line"><span>岗位</span></span>
<span class="line"><span>  ↓ 实例化为</span></span>
<span class="line"><span>数字员工</span></span>
<span class="line"><span>  ↓ 绑定</span></span>
<span class="line"><span>Agent Provider + Skill + Tool + Runtime</span></span></code></pre></div><p>若从 Agent 和 Prompt 开始，只会得到一个技术上能执行的对象，却没有稳定的组织理由、边界和责任人。</p><h3 id="数字员工不等于单个-agent" tabindex="-1">数字员工不等于单个 Agent <a class="header-anchor" href="#数字员工不等于单个-agent" aria-label="Permalink to &quot;数字员工不等于单个 Agent&quot;">​</a></h3><p>当前产品多数仍把 Agent 作为治理单位，但它们提出的治理要求实际上指向更高层抽象。一个数字员工可以在不同时间使用不同模型、临时 Session、下属 Specialist Agent、工具和人工审批，但仍代表同一个岗位。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>数字员工 ≠ 模型 Session</span></span>
<span class="line"><span>数字员工 ≠ Prompt</span></span>
<span class="line"><span>数字员工 ≠ 单一 Agent 进程</span></span>
<span class="line"><span></span></span>
<span class="line"><span>数字员工 = 持久的组织工作身份</span></span></code></pre></div><h3 id="岗位与-owner-必须分开表达" tabindex="-1">岗位与 Owner 必须分开表达 <a class="header-anchor" href="#岗位与-owner-必须分开表达" aria-label="Permalink to &quot;岗位与 Owner 必须分开表达&quot;">​</a></h3><p>岗位定义“存在什么工作”；Owner 定义“谁对这个数字员工持续负责”。二者不能合并为一个字段，否则岗位调整、责任转移和跨团队治理会变得困难。</p><p>最小 Registry 研究投影可以包括：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">digital_employee</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  position_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  organizational_owner</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  responsibility_scope</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  authority_policy_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  allowed_work_catalog_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  escalation_policy_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  lifecycle_status</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  runtime_binding_refs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  evaluation_summary_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span></code></pre></div><p>这只是研究投影，不是冻结实施 Schema。</p><h2 id="engineering-impact" tabindex="-1">Engineering Impact <a class="header-anchor" href="#engineering-impact" aria-label="Permalink to &quot;Engineering Impact&quot;">​</a></h2><h3 id="tmpa" tabindex="-1">TMPA <a class="header-anchor" href="#tmpa" aria-label="Permalink to &quot;TMPA&quot;">​</a></h3><p>本研究笔记不直接修改 TMPA 正式出版物。作为研究输入，它强化了组织角色、权限、责任、事件历史与治理判断之间需要显式 Reference 的必要性。</p><h3 id="digital-employee" tabindex="-1">Digital Employee <a class="header-anchor" href="#digital-employee" aria-label="Permalink to &quot;Digital Employee&quot;">​</a></h3><p>岗位、Owner、责任和权限应成为一等架构对象。数字员工定义不应从模型或 Agent 框架开始。</p><h3 id="codeflowmu" tabindex="-1">CodeFlowMu <a class="header-anchor" href="#codeflowmu" aria-label="Permalink to &quot;CodeFlowMu&quot;">​</a></h3><p>现有 PM、DEV、QA、OPS 可以被视为早期岗位定义。未来 Digital Employee Registry 应投影：</p><ul><li>岗位身份；</li><li>人类或组织 Owner；</li><li>可接受的 WorkOrder 类型；</li><li>允许的 Tool 与 Provider；</li><li>升级与完成权限；</li><li>生命周期与评估状态。</li></ul><p>第一步应是对现有 Runtime 事实建立只读投影，而不是立刻重写派发行为。</p><h2 id="future-work" tabindex="-1">Future Work <a class="header-anchor" href="#future-work" aria-label="Permalink to &quot;Future Work&quot;">​</a></h2><ol><li>定义最小 Position Contract。</li><li>分离 Position、Digital Employee Instance、Agent Provider 与 Session 标识。</li><li>定义 Owner 转移对活动 WorkOrder 的影响。</li><li>对照 Workday、ServiceNow、Microsoft 的岗位权限模型与 CodeFlowMu 当前 TeamPolicy、FCoP 责任模型。</li><li>明确数字员工进入生产前需要哪些激活证据。</li></ol><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li>Workday，<strong>Agent System of Record</strong>：<a href="https://www.workday.com/en-us/artificial-intelligence/agent-system-of-record.html" target="_blank" rel="noreferrer">https://www.workday.com/en-us/artificial-intelligence/agent-system-of-record.html</a></li><li>Workday，<strong>The Workday Agent System of Record Is Now Generally Available</strong>：<a href="https://blog.workday.com/en-us/managing-ai-powered-future-of-work.html" target="_blank" rel="noreferrer">https://blog.workday.com/en-us/managing-ai-powered-future-of-work.html</a></li><li>Workday，<strong>Understanding AI agents</strong>：<a href="https://www.workday.com/en-us/topics/ai/ai-agents.html" target="_blank" rel="noreferrer">https://www.workday.com/en-us/topics/ai/ai-agents.html</a></li><li>ServiceNow，<strong>ServiceNow launches Autonomous Workforce that thinks and acts</strong>：<a href="https://newsroom.servicenow.com/press-releases/details/2026/ServiceNow-launches-Autonomous-Workforce-that-thinks-and-acts-adds-Moveworks-to-the-ServiceNow-AI-Platform/default.aspx" target="_blank" rel="noreferrer">https://newsroom.servicenow.com/press-releases/details/2026/ServiceNow-launches-Autonomous-Workforce-that-thinks-and-acts-adds-Moveworks-to-the-ServiceNow-AI-Platform/default.aspx</a></li><li>Microsoft Learn，<strong>Microsoft Agent 365 overview</strong>：<a href="https://learn.microsoft.com/en-us/microsoft-agent-365/overview" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/microsoft-agent-365/overview</a></li><li>Microsoft Learn，<strong>Govern agents using Agent 365</strong>：<a href="https://learn.microsoft.com/en-us/training/modules/agent-365-govern/" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/training/modules/agent-365-govern/</a></li><li>Microsoft Learn，<strong>Governance and lifecycle actions for agents</strong>：<a href="https://learn.microsoft.com/en-us/microsoft-365/admin/manage/agent-actions?view=o365-worldwide" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/microsoft-365/admin/manage/agent-actions?view=o365-worldwide</a></li><li>Microsoft Learn，<strong>Protect agent identities with Microsoft Entra</strong>：<a href="https://learn.microsoft.com/en-us/microsoft-agent-365/admin/capabilities-entra" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/microsoft-agent-365/admin/capabilities-entra</a></li></ol>`,52))])}const f=s(l,[["render",p]]);export{m as __pageData,f as default};
